      pt: ["Fortificação medieval", "Perto de Kirchberg am Wechsel", "Ruína de acesso livre", "Arqueologicamente significativa"],
      fr: ["Fortification médiévale", "Près de Kirchberg am Wechsel", "Ruine en accès libre", "Importance archéologique"],
