      es: ["Origen en el siglo XII", "Situado en el Industrieviertel", "Restos de muros bien visibles", "Vistas al valle de Piesting"],
      pt: ["Origem no século XII", "Localizado no Industrieviertel", "Restos de muralhas bem visíveis", "Vista para o vale de Piesting"],
      fr: ["Origine au XIIe siècle", "Situé dans l'Industrieviertel", "Restes de murs bien visibles", "Vue sur la vallée de la Piesting"],
