      es: ["Waldviertel", "Historia fronteriza", "Restos de fortificación", "Entorno boscoso"],
      pt: ["Waldviertel", "História fronteiriça", "Restos de fortificação", "Ambiente arborizado"],
      fr: ["Waldviertel", "Histoire frontalière", "Restes de fortification", "Environnement boisé"],
