      hu: "A várrom Piesting közelében található. A középkori építmény maradványai népszerű célpontok a történelem iránt érdeklődő túrázóknak.",
      ro: "Ruinele castelului se află lângă Piesting. Rămășițele complexului medieval sunt o destinație populară pentru drumeții interesați de istorie.",
