      ro: ["Clădire renascentistă", "Fost palat de vânătoare", "Situat în Viena", "Utilizare culturală"],
      en: ["Renaissance building", "Former hunting lodge", "Located in Vienna", "Cultural use"],
      es: ["Edificio renacentista", "Antiguo pabellón de caza", "Situado en Viena", "Uso cultural"],
      pt: ["Edifício renascentista", "Antigo pavilhão de caça", "Situado em Viena", "Uso cultural"],
      fr: ["Bâtiment Renaissance", "Ancien pavillon de chasse", "Situé à Vienne", "Usage culturel"],
