    imageHint: "Schwarzenbach castle ruins landscape",
    descriptionAdvanced: {
      de: "Die Burgruine Schwarzenbach liegt in der Buckligen Welt in Niederösterreich und thront strategisch günstig auf einem Hügel über dem Tal der Schwarzenbach. Erste Erwähnungen der Anlage datieren auf das Jahr 1170, wobei sie über Jahrhunderte als wichtige Grenzbefestigung gegen die aus dem Osten eindringenden Heere diente. Ein markanter Wendepunkt in der Geschichte war das Jahr 1589, als das Anwesen in den Besitz der Familie Esterházy gelangte. Während der Türkenkriege von 1683 wurde die Burg erfolgreich gegen die osmanischen Truppen verteidigt, verlor jedoch im 18. Jahrhundert an Bedeutung und wurde schließlich aufgegeben. Heute sind die imposanten Reste der Kernburg und der weitreichenden Wehrmauern ein geschütztes Kulturdenkmal. Besonders interessant ist die archäologische Bedeutung des Hügels, da sich hier auch eine bedeutende keltische Wallanlage befindet, die alljährlich beim Keltenfestival im Mittelpunkt steht.",
      hu: "A Schwarzenbach várrom az alsó-ausztriai Bucklige Welt régióban található, és stratégiailag kedvező helyen, a Schwarzenbach völgye feletti dombon magasodik. A létesítmény első említése 1170-ből származik, és évszázadokon át fontos határerődítményként szolgált a keletről betörő seregek ellen. A történelem jelentős fordulópontja 1589 volt, amikor az ingatlan az Esterházy család birtokába került. Az 1683-as török háborúk idején a várat sikeresen megvédték az oszmán csapatok ellen, ám a 18. században elvesztette jelentőségét, és végül elhagyták. Ma a magvár és a kiterjedt védőfalak impozáns maradványai védett kulturális műemlékek. Különösen érdekes a domb régészeti jelentősége, mivel itt egy jelentős kelta sáncrendszer is található, amely a minden évben megrendezett Kelta Fesztivál központjában áll.",
      ro: "Ruinele Castelului Schwarzenbach sunt situate în regiunea Bucklige Welt din Austria Inferioară și tronează strategic pe un deal deasupra văii râului Schwarzenbach. Primele mențiuni ale complexului datează din anul 1170, servind timp de secole ca o fortificație de frontieră importantă împotriva armatelor care invadau din est. Un punct de cotitură marcant în istorie a fost anul 1589, când proprietatea a intrat în posesia familiei Esterházy. În timpul războaielor cu turcii din 1683, castelul a fost apărat cu succes împotriva trupelor otomane, dar și-a pierdut importanța în secolul al XVIII-lea și a fost în cele din urmă abandonat. Astăzi, resturile impunătoare ale cetății centrale și zidurile de apărare extinse sunt monumente culturale protejate. Interesantă este semnificația arheologică a dealului, deoarece aici se află și o fortificație celtică importantă, care este punctul central al festivalului celt de anual.",
      en: "The Schwarzenbach Castle ruins are located in the Bucklige Welt region of Lower Austria and stand strategically on a hill above the Schwarzenbach valley. First mentions of the complex date back to 1170, and it served for centuries as an important border fortification against invading armies from the east. A significant turning point in its history was the year 1589, when the estate came into the possession of the Esterházy family. During the Turkish wars of 1683, the castle was successfully defended against Ottoman troops, but it lost its importance in the 18th century and was eventually abandoned. Today, the imposing remains of the core castle and the extensive defensive walls are a protected cultural monument. Of particular interest is the archaeological significance of the hill, as it also houses a major Celtic hillfort, which is the center of the annual Celtic Festival.",
      es: "Las ruinas del castillo de Schwarzenbach se encuentran en la Bucklige Welt, en la Baja Austria, y se alzan estratégicamente en una colina sobre el valle del río Schwarzenbach. Las primeras menciones del complejo datan del año 1170, habiendo servido durante siglos como una importante fortificación fronteriza contra los ejércitos que invadían desde el este. Un punto de inflexión marcado en su historia fue el año 1589, cuando la propiedad pasó a manos de la familia Esterházy. Durante las guerras turcas de 1683, el castillo fue defendido con éxito contra las tropas otomanas, pero perdió importancia en el siglo XVIII y fue finalmente abandonado. Hoy en día, los imponentes restos del castillo central y de las extensas murallas defensivas son un monumento cultural protegido. Especialmente interesante es la importancia arqueológica de la colina, ya que aquí también se encuentra una importante fortificación celta, que es el centro de atención cada año durante el Festival Celta.",
      pt: "As ruínas do castelo de Schwarzenbach encontram-se na Bucklige Welt, na Baixa Áustria, e erguem-se estrategicamente numa colina sobre o vale do rio Schwarzenbach. As primeiras menções do complexo datam do ano 1170, tendo servido durante séculos como uma importante fortificação fronteiriça contra os exércitos que invadiam do leste. Um ponto de viragem marcado na sua história foi o ano 1589, quando a propriedade passou para as mãos da família Esterházy. Durante as guerras turcas de 1683, o castelo foi defendido com sucesso contra as tropas otomanas, mas perdeu importância no século XVIII e foi finalmente abandonado. Hoje em dia, os imponentes restos do castelo central e das extensas muralhas defensivas são um monumento cultural protegido. Especialmente interessante é a importância arqueológica da colina, já que aqui também se encontra uma importante fortificação celta, que é o centro das atenções todos os anos durante o Festival Celta.",
      fr: "La ruine du château de Schwarzenbach se situe dans la Bucklige Welt en Basse-Autriche et trône stratégiquement sur une colline dominant la vallée de la Schwarzenbach. Les premières mentions de l'ensemble datent de 1170, celui-ci ayant servi pendant des siècles d'importante fortification frontalière contre les armées venant de l'Est. Un tournant marqué dans son histoire fut l'année 1589, lorsque le domaine devint la propriété de la famille Esterházy. Lors des guerres turques de 1683, le château fut défendu avec succès contre les troupes ottomanes, mais perdit de son importance au XVIIIe siècle et fut finalement abandonné. Aujourd'hui, les vestiges imposants du cœur du château et des vastes murs de défense sont un monument culturel protégé. L'importance archéologique de la colline est particulièrement intéressante, car on y trouve également d'importants remparts celtiques, au cœur du festival celte annuel.",
    },
